const toOpaque = (rgb: string, alpha: number, base: number = 255) => {
  const [r, g, b] = rgb.split(" ").map(Number)
  const blend = (c: number) => Math.round(c * alpha + base * (1 - alpha))
  return `rgb(${blend(r)} ${blend(g)} ${blend(b)})`
}

